-- Local AI shopping demo. Synthetic products; no real brand claims or payments.
-- INSERT-only: existing rows with the same primary key are preserved.
SET NAMES utf8mb4;
START TRANSACTION;
COMMIT;
SELECT product_id,product_name,status,min_price,max_price FROM simlect_product.product_info WHERE product_id LIKE 'DEMOAI%' ORDER BY product_id;
